package com.greenocean.backend.trust;
import org.springframework.stereotype.Service;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.annotation.Transactional;import java.time.*;import java.util.*;import com.greenocean.backend.common.exception.*;
/** Approved fixed factual templates; confidential incident evidence is never included in notices. */
@Service @Transactional
public class OperationsCommunications {
 private final JdbcTemplate db;private final IncidentOperations operations;private final TrustAuthority authority;
 public OperationsCommunications(JdbcTemplate db,IncidentOperations operations,TrustAuthority authority){this.db=db;this.operations=operations;this.authority=authority;}
 private String message(String code,String locale){boolean fa="fa".equals(locale);return switch(code){case"SERVICE_INTERRUPTION"->fa?"برخی قابلیت‌های این خدمت موقتاً در دسترس نیستند. برای وضعیت حساب، برنامه را بررسی کنید. تعهدات موجود خودکار لغو نشده‌اند.":"Some service features are temporarily unavailable. Check the app for your account status. Existing obligations have not been automatically cancelled.";case"SERVICE_RESTORED"->fa?"بررسی فنی بازیابی خدمت ثبت شده است. دسترسی هر قابلیت همچنان به شرایط و مجوزهای فعلی بستگی دارد.":"A technical service recovery review has been recorded. Each feature remains subject to current eligibility and approvals.";case"CONTACT_SUPPORT"->fa?"برای بررسی وضعیت خدمت، از مسیر پشتیبانی داخل حساب استفاده کنید. پاسخ فوری تضمین نمی‌شود.":"Use authenticated account support to review your service status. Immediate response is not guaranteed.";default->throw new IllegalArgumentException("Choose a fixed factual communication template");};}
 public UUID draft(UUID who,UUID sid,UUID incident,long revision,String template,String locale,boolean publicStatus,List<UUID> targets){var r=operations.lock(who,sid,incident);operations.exact(r,revision);if(!Set.of("en","fa").contains(locale)||targets==null||targets.size()>50||targets.stream().anyMatch(Objects::isNull)||new HashSet<>(targets).size()!=targets.size()||(!publicStatus&&targets.isEmpty()))throw new IllegalArgumentException("Choose English/Persian and up to fifty distinct authenticated recipients or a public status");message(template,locale);if("SERVICE_RESTORED".equals(template)&&!Set.of("RESOLVED","POST_INCIDENT_REVIEW","CLOSED").contains(r.get("state")))throw new ConflictException("A recorded recovery must precede a restored-service notice");if(!who.equals(r.get("owner_id")))throw new ForbiddenException("The accountable incident owner must draft communication");authority.budget(who,"INCIDENT_COMMUNICATION_DRAFTED",10);UUID id=UUID.randomUUID();db.update("INSERT INTO operation_communications(id,incident_id,incident_revision,template,locale,public_status,author_id,author_session,author_version,expires_at) VALUES(?,?,?,?,?,?,?,?,?,CURRENT_TIMESTAMP+INTERVAL '15 minutes')",id,incident,revision,template,locale,publicStatus,who,sid,operations.version(who,sid));for(UUID target:targets){if(!Boolean.TRUE.equals(db.queryForObject("SELECT EXISTS(SELECT 1 FROM users WHERE id=? AND status='ACTIVE' AND email_verified AND deleted_at IS NULL)",Boolean.class,target)))throw new ConflictException("Each targeted recipient must be a current active authenticated account");db.update("INSERT INTO operation_communication_targets(communication_id,user_id) VALUES(?,?)",id,target);}return id;}
 public void approve(UUID who,UUID sid,UUID incident,UUID communication,long revision){var hint=db.queryForList("SELECT author_id FROM operation_communications WHERE id=? AND incident_id=?",communication,incident);if(hint.isEmpty())throw new NotFoundException("Communication unavailable");db.queryForList("SELECT id FROM users WHERE id=? FOR SHARE",hint.getFirst().get("author_id"));var r=operations.lock(who,sid,incident);operations.exact(r,revision);String domain=(String)r.get("domain");operations.staffed(who,domain);var c=db.queryForMap("SELECT *,expires_at>CURRENT_TIMESTAMP AS live FROM operation_communications WHERE id=? AND incident_id=? FOR UPDATE",communication,incident);if(who.equals(c.get("author_id")))throw new ForbiddenException("A second independent operator must approve communication");if(c.get("approved_at")!=null||c.get("revoked_at")!=null||!Boolean.TRUE.equals(c.get("live"))||((Number)c.get("incident_revision")).longValue()!=revision)throw new ConflictException("Fresh exact-revision communication review required");UUID author=(UUID)c.get("author_id"),authorSid=(UUID)c.get("author_session");operations.require(author,authorSid,domain);operations.staffed(author,domain);if(!Objects.equals(c.get("author_version"),operations.version(author,authorSid)))throw new ConflictException("Communication author session changed");if("SERVICE_RESTORED".equals(c.get("template"))&&!Set.of("RESOLVED","POST_INCIDENT_REVIEW","CLOSED").contains(r.get("state")))throw new ConflictException("Current recovery evidence required");db.update("UPDATE operation_communications SET approved_at=CURRENT_TIMESTAMP,reviewer_id=?,expires_at=CURRENT_TIMESTAMP+INTERVAL '24 hours' WHERE id=?",who,communication);
  String title="fa".equals(c.get("locale"))?"وضعیت خدمت":"Service status",body=message((String)c.get("template"),(String)c.get("locale"));for(var target:db.queryForList("SELECT t.user_id FROM operation_communication_targets t JOIN users u ON u.id=t.user_id WHERE t.communication_id=? AND t.notification_id IS NULL AND u.status='ACTIVE' AND u.deleted_at IS NULL",communication)){UUID notification=db.queryForObject("INSERT INTO notifications(user_id,type,title,body) VALUES(?,'SYSTEM_NOTICE',?,?) RETURNING id",UUID.class,target.get("user_id"),title,body);db.update("UPDATE operation_communication_targets SET notification_id=? WHERE communication_id=? AND user_id=?",notification,communication,target.get("user_id"));}authority.audit(who,incident,"INCIDENT_COMMUNICATION_APPROVED");
 }
 public List<Map<String,Object>> queue(UUID who,UUID sid,UUID incident){operations.lock(who,sid,incident);return db.queryForList("SELECT c.id,c.incident_revision,c.template,c.locale,c.public_status,c.author_id=? AS own_draft,c.approved_at,c.expires_at,c.revoked_at,(SELECT count(*) FROM operation_communication_targets t WHERE t.communication_id=c.id) AS targeted_count,(SELECT count(*) FROM operation_communication_targets t WHERE t.communication_id=c.id AND t.notification_id IS NOT NULL) AS inbox_created_count,(SELECT count(*) FROM operation_communication_targets t JOIN notifications n ON n.id=t.notification_id WHERE t.communication_id=c.id AND n.is_read) AS inbox_read_count FROM operation_communications c WHERE c.incident_id=? ORDER BY c.created_at DESC LIMIT 50",who,incident);}
 @Transactional(readOnly=true)public List<Map<String,Object>> publicStatus(String locale){if(!Set.of("en","fa").contains(locale))throw new IllegalArgumentException("Choose English or Persian");var rows=db.queryForList("SELECT DISTINCT ON(i.domain)c.template,c.locale,i.domain,c.approved_at FROM operation_communications c JOIN operation_incidents i ON i.id=c.incident_id JOIN users u ON u.id=c.reviewer_id WHERE c.public_status AND c.revoked_at IS NULL AND c.locale=? AND c.approved_at IS NOT NULL AND c.expires_at>CURRENT_TIMESTAMP AND u.status='ACTIVE' AND u.deleted_at IS NULL AND EXISTS(SELECT 1 FROM user_roles ur JOIN roles r ON r.id=ur.role_id WHERE ur.user_id=u.id AND r.name='TRUST_'||CASE i.domain WHEN 'GROUP' THEN 'SOCIAL' ELSE i.domain END) ORDER BY i.domain,c.approved_at DESC,c.id DESC",locale);for(var r:rows){r.put("message",message((String)r.remove("template"),locale));r.remove("locale");}return rows;}
}
